class Solution {
  public int maximumSaleItems(int[][] items, int budget) {
    int n = items.length;
    int[] cnt = new int[n + 1];
    long minPrice = Long.MAX_VALUE;
    for (int[] it : items) {
      cnt[it[0]]++;
      minPrice = Math.min(minPrice, it[1]);
    }
    long[] free = new long[n + 1];
    for (int f = 1; f <= n; f++) {
      long c = 0;
      for (int m = f; m <= n; m += f) c += cnt[m];
      free[f] = c - 1;
    }
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    java.util.Arrays.sort(order, (a, b) -> Integer.compare(items[a][1], items[b][1]));
    long remaining = budget, total = 0;
    for (int idx : order) {
      long price = items[idx][1], slots = free[items[idx][0]];
      if (slots <= 0 || price >= 2 * minPrice) continue;
      long take = Math.min(slots, remaining / price);
      remaining -= take * price;
      total += 2 * take;
    }
    return (int) (total + remaining / minPrice);
  }
}
